import{_ as n,o as t,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const o="/images/logic-studio/user-guide/blocks-js-de.png",p=JSON.parse('{"title":"Blocks JS","description":"","frontmatter":{},"headers":[],"relativePath":"projects/logic-studio/user-guide/blocks-js.md","filePath":"projects/logic-studio/user-guide/blocks-js.md","lastUpdated":1794859658000}'),a={name:"projects/logic-studio/user-guide/blocks-js.md"};function s(l,e,d,u,h,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="blocks-js" tabindex="-1">Blocks JS <a class="header-anchor" href="#blocks-js" aria-label="Permalink to &quot;Blocks JS&quot;">​</a></h1><h2 id="erstes-beispiel" tabindex="-1">Erstes Beispiel <a class="header-anchor" href="#erstes-beispiel" aria-label="Permalink to &quot;Erstes Beispiel&quot;">​</a></h2><p>Der Testlauf liest einen simulierten Entitätszustand und schreibt ihn ins Protokoll.</p><ol><li>Wähle <strong>Neues Projekt → Blocks JS</strong>. Öffne <strong>System</strong> und ziehe <strong>debug output</strong> in den Arbeitsbereich.</li><li>Ziehe <strong>Zustand von Entität</strong> aus derselben Kategorie in den freien Werteanschluss von <strong>debug output</strong>. Wähle deine Testentität. Im Bild ist es <code>binary_sensor.bewegung</code>.</li><li>Wähle <strong>Testlauf starten</strong>. Unter <strong>Protokoll</strong> stehen der gelesene Zustand und die Ausgabemeldung. In der Demo steht dort <code>on</code>. Der Testlauf sendet hier keinen Schaltbefehl.</li></ol><p><a href="/images/logic-studio/user-guide/blocks-js-de.png"><img src="'+o+'" alt="Blocks JS mit verbundenem Entitätsblock und Zustand on im Protokoll"></a></p><h2 id="funktionen" tabindex="-1">Funktionen <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Funktionen&quot;">​</a></h2><h3 id="system-aktionen-und-sendto" tabindex="-1">System, Aktionen und Sendto <a class="header-anchor" href="#system-aktionen-und-sendto" aria-label="Permalink to &quot;System, Aktionen und Sendto&quot;">​</a></h3><p>Lies Entitäten, schalte freigegebene Ziele, sende Nachrichten oder nutze eine Verlaufsabfrage. Dynamische Anschlüsse nehmen zum Beispiel eine Entitäts-ID aus einer Schleife an.</p><h3 id="trigger-datum-und-timeouts" tabindex="-1">Trigger, Datum und Timeouts <a class="header-anchor" href="#trigger-datum-und-timeouts" aria-label="Permalink to &quot;Trigger, Datum und Timeouts&quot;">​</a></h3><p>Starte Aktionen bei Zustandsänderung, Astrozeit oder Zeitplan. Nutze einfache oder benannte CRON-Pläne, Verzögerungen und Intervalle. Benannte Läufe lassen sich stoppen.</p><h3 id="werte-bearbeiten" tabindex="-1">Werte bearbeiten <a class="header-anchor" href="#werte-bearbeiten" aria-label="Permalink to &quot;Werte bearbeiten&quot;">​</a></h3><p>Konvertierung, Objekt, Logik, Mathematik, Text, Listen und Farbe liefern Werte, die du in andere Blöcke stecken kannst. Schleifen wiederholen Abläufe.</p><h3 id="variablen-und-funktionen" tabindex="-1">Variablen und Funktionen <a class="header-anchor" href="#variablen-und-funktionen" aria-label="Permalink to &quot;Variablen und Funktionen&quot;">​</a></h3><p>Speichere Zwischenwerte in Variablen. Funktionen bündeln Schritte, können Werte zurückgeben und lassen sich erneut aufrufen.</p><h3 id="iobroker-import" tabindex="-1">ioBroker-Import <a class="header-anchor" href="#iobroker-import" aria-label="Permalink to &quot;ioBroker-Import&quot;">​</a></h3><p>Öffne im Expertenmodus <strong>ioBroker-Export einfügen</strong>, füge den Export ein und prüfe die Übersicht. Wähle HA-Entitäten ausdrücklich zu und beachte Hinweise direkt am Block.</p><h3 id="berechnete-iobroker-id-auf-existenz-prufen" tabindex="-1">Berechnete ioBroker-ID auf Existenz prüfen <a class="header-anchor" href="#berechnete-iobroker-id-auf-existenz-prufen" aria-label="Permalink to &quot;Berechnete ioBroker-ID auf Existenz prüfen&quot;">​</a></h3><p>Wenn dein ioBroker-Skript eine ID aus mehreren Textteilen zusammensetzt, kannst du sie mit dem importierten Block <code>state_exists_var</code> prüfen.</p><ol><li>Öffne die Importprüfung und trage im Feld <strong>ID-Zuordnung (JSON)</strong> die fertig zusammengesetzte ioBroker-ID und die dazugehörige HA-Entitäts-ID ein, zum Beispiel <code>{&quot;0_userdata.0.garten.pumpe&quot;:&quot;switch.gartenpumpe&quot;}</code>. Das Feld findest du auch am importierten Block.</li><li>Gib die zugeordnete Entität in den App-Einstellungen unter <code>runtime_read_entities</code> frei, sofern sie noch keine Schreibfreigabe hat.</li><li>Speichere das Projekt und starte <strong>Play</strong>. Eine vorhandene HA-Entität ergibt <code>true</code>, eine zugeordnete, aber fehlende Entität <code>false</code>. Fehlt für die berechnete ID ein Eintrag, stoppt der Lauf und nennt die ID im Protokoll. Ergänze den Eintrag am Block und starte erneut.</li></ol><h3 id="einen-iobroker-datenpunkt-als-ha-helfer-ubernehmen" tabindex="-1">Einen ioBroker-Datenpunkt als HA-Helfer übernehmen <a class="header-anchor" href="#einen-iobroker-datenpunkt-als-ha-helfer-ubernehmen" aria-label="Permalink to &quot;Einen ioBroker-Datenpunkt als HA-Helfer übernehmen&quot;">​</a></h3><p>Wenn dein Blockly-Export den Block <strong>Datenpunkt erzeugen</strong> (<code>createState</code>) enthält, kannst du den Wert in einem Home-Assistant-Helfer speichern. Der Helfer erscheint in Home Assistant unter <strong>Einstellungen → Geräte &amp; Dienste → Helfer</strong>.</p><ol><li>Öffne <strong>Expertenwerkzeuge → ioBroker-Export einfügen</strong> und klicke nach dem Einfügen auf <strong>Import prüfen</strong>.</li><li>Wähle für die ioBroker-ID eine der drei Möglichkeiten: <ul><li><strong>Helfer zuordnen</strong> verwendet einen vorhandenen Helfer. Sein aktueller Wert bleibt erhalten.</li><li><strong>Helfer anlegen</strong> schlägt aus dem Datentyp einen Schalter, Zahlen- oder Texthelfer vor. Prüfe und bestätige den Namen. Das Anlegen erfordert ein HA-Administratorkonto. Ein unterstützter fester Startwert wird einmalig gesetzt. Bei einem berechneten Startwert kannst du einen Helfer in HA vorbereiten und zuordnen.</li><li><strong>Später zuordnen</strong> lässt die Zuordnung offen. Öffne das Projekt und wähle vor dem Start im importierten Block eine passende HA-Entität aus.</li></ul></li><li>Prüfe, ob die Blöcke zum Erzeugen, Lesen und Aktualisieren derselben ioBroker-ID auf dieselbe HA-Entität zeigen. Wähle <strong>Als Projekt öffnen</strong> und speichere das Projekt.</li><li>Gib den Helfer in den App-Optionen unter <code>runtime_read_entities</code> und für das Aktualisieren zusätzlich unter <code>runtime_write_entities</code> frei. Starte das gespeicherte Skript mit <strong>Play</strong>. Das Skript greift auf den aktuellen Wert des Helfers zu, auch wenn du ihn in Home Assistant änderst.</li></ol><p>Im Beispiel wird ein Zahlenhelfer mit <strong>17</strong> angelegt. Im Protokoll steht beim ersten Start <strong>17</strong> und das Skript schreibt <strong>42</strong>. Nach einem Skriptneustart steht im Protokoll <strong>42</strong>. So kannst du prüfen, ob der Startwert nur bei der Anlage gesetzt wurde. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/ha-logic-studio-pro-v0.1.122/ha_logic_studio_pro/tests/fixtures/iobroker-create-state.xml" target="_blank" rel="noreferrer">Blockly-Beispiel</a></p><h3 id="http-in-importierten-blocken" tabindex="-1">HTTP in importierten Blöcken <a class="header-anchor" href="#http-in-importierten-blocken" aria-label="Permalink to &quot;HTTP in importierten Blöcken&quot;">​</a></h3><p>Ordne einen freigegebenen HA-REST-Befehl zu. URL, Timeout und zusätzliche Request-Header werden in HA konfiguriert. Der importierte Content-Type steht als Vorgabe im POST-Block.</p><h3 id="testlauf-und-play" tabindex="-1">Testlauf und Play <a class="header-anchor" href="#testlauf-und-play" aria-label="Permalink to &quot;Testlauf und Play&quot;">​</a></h3><p>Der Testlauf simuliert. Speichere vor Play und schau im Protokoll nach, ob die echte HA-Aktion ausgeführt wurde.</p><h2 id="einen-import-schritt-fur-schritt-prufen" tabindex="-1">Einen Import Schritt für Schritt prüfen <a class="header-anchor" href="#einen-import-schritt-fur-schritt-prufen" aria-label="Permalink to &quot;Einen Import Schritt für Schritt prüfen&quot;">​</a></h2><ol><li>Öffne das Projektmenü und schalte den <strong>Expertenmodus</strong> ein. Öffne im Editor <strong>Expertenwerkzeuge → ioBroker-Export einfügen</strong>.</li><li>Füge das Blockly-XML oder einen ioBroker-JavaScript-Export mit eingebetteten Blockly-Daten ein. Klicke <strong>Import prüfen</strong>. Die Liste zeigt, welche Blöcke übernommen wurden und wo eine Zuordnung fehlt.</li><li>Klicke <strong>Als Projekt öffnen</strong> und ergänze die Hinweise direkt an den betroffenen Blöcken. Bei einem importierten POST trägst du beispielsweise den HA-REST-Befehl ein, der die Header und den Zeitrahmen definiert.</li><li>Speichere den Entwurf und starte zuerst den <strong>Testlauf</strong>. Für die echte Ausführung wähle danach <strong>Play</strong>. Öffne das <strong>Protokoll</strong>, kontrolliere die Ausgabe und beende den Lauf mit <strong>Stopp</strong>.</li></ol><h2 id="wenn-etwas-nicht-klappt" tabindex="-1">Wenn etwas nicht klappt <a class="header-anchor" href="#wenn-etwas-nicht-klappt" aria-label="Permalink to &quot;Wenn etwas nicht klappt&quot;">​</a></h2><p>Wenn der Import einen Platzhalter zeigt, lies den Blockhinweis und ersetze oder ergänze den Block vor dem Start.</p>',31)])])}const f=n(a,[["render",s]]);export{p as __pageData,f as default};
